// swift-tools-version:5.9
//
// The Swift package over the writemorebetter checker. It contains two Swift files (the UniFFI
// bindings generated by scripts/build-xcframework.sh and a small NSRange helper) and one binary
// target: the XCFramework that the same script writes to dist/.
//
// Local development (a checkout you just ran the script in) uses the path-based binary target.
// A released tag has no dist/ — it is git-ignored — so the target uses the url and checksum
// literals below, which the release workflow rewrites before it tags. They have to be literals
// inside this file rather than a sibling: SwiftPM compiles a remote dependency's manifest from a
// virtual filesystem where nothing but the manifest is readable, so any FileManager read of a
// neighbouring file fails at manifest load for every consumer. SwiftPM caches the evaluated
// manifest by contents, so `swift package purge-cache` is needed if this checkout was first
// resolved before the framework was built. See swift/README.md.
import Foundation
import PackageDescription

let packageDirectory = Context.packageDirectory
let localFramework = "\(packageDirectory)/dist/WriteMoreBetterFFI.xcframework"

let ffiTarget: Target
if FileManager.default.fileExists(atPath: localFramework) {
    ffiTarget = .binaryTarget(
        name: "WriteMoreBetterFFI",
        path: "dist/WriteMoreBetterFFI.xcframework"
    )
} else {
    ffiTarget = .binaryTarget(
        name: "WriteMoreBetterFFI",
        url: "https://github.com/cmlarsen/writemorebetter/releases/download/0.8.0/WriteMoreBetterFFI.xcframework.zip",
        checksum: "7fbdeb61a7dd82e19372f20b0ecc974031419c0712a7fa83a1fa984bb48ca9a7"
    )
}

let package = Package(
    name: "WriteMoreBetter",
    platforms: [
        .macOS(.v12),
        .iOS(.v16),
    ],
    products: [
        .library(name: "WriteMoreBetter", targets: ["WriteMoreBetter"]),
    ],
    targets: [
        .target(
            name: "WriteMoreBetter",
            dependencies: ["WriteMoreBetterFFI"],
            path: "swift/Sources/WriteMoreBetter"
        ),
        .testTarget(
            name: "WriteMoreBetterTests",
            dependencies: ["WriteMoreBetter"],
            path: "swift/Tests/WriteMoreBetterTests"
        ),
        ffiTarget,
    ]
)
